    n = int(input().strip())
    grid = [[0] * n for _ in range(n)]
    turn = 0

    while turn < n * n:
        a = int(input().strip())
        placed = False
        for i in range(n):
            for j in range(n):
                if grid[i][j] == 0:
                    valid_colors = {1, 2, 3} - {a}
                    if i > 0 and grid[i-1][j] in valid_colors:
                        valid_colors.remove(grid[i-1][j])
                    if i < n-1 and grid[i+1][j] in valid_colors:
                        valid_colors.remove(grid[i+1][j])
                    if j > 0 and grid[i][j-1] in valid_colors:
                        valid_colors.remove(grid[i][j-1])
                    if j < n-1 and grid[i][j+1] in valid_colors:
                        valid_colors.remove(grid[i][j+1])
                    if valid_colors:
                        b = valid_colors.pop()
                        grid[i][j] = b
                        print(f"{b} {i+1} {j+1}")
                        sys.stdout.flush()
                        placed = True
                        break
            if placed:
                break
        turn += 1

if __name__ == "__main__":
    main()
